const ALLOWED = ['Conforme', 'Parcial', 'Divergente', 'Sem base', 'Sem afirmações verificáveis'];
const clean = (s) => String(s || '').replace(/\s*\n+\s*/g, ' | ').replace(/"/g, "'").trim().slice(0, 2000);

return $input.all().map(item => {
  const raw = item.json.output || item.json.text || '';
  let status = 'Erro na validação';
  let divergencias = '';
  let fontes = '';

  if (item.json.error && !raw) {
    divergencias = 'Falha na consulta à base oficial: ' + clean(item.json.error.message || item.json.error);
  } else {
    try {
      const m = String(raw).match(/\{[\s\S]*\}/);
      if (!m) throw new Error('sem JSON');
      const p = JSON.parse(m[0]);
      status = ALLOWED.includes(p.status_factual) ? p.status_factual : 'Erro na validação';
      divergencias = clean(p.divergencias);
      fontes = clean(p.fontes);
    } catch (e) {
      // Fallback por regex se a resposta vier truncada
      const s = String(raw).match(/"status_factual"\s*:\s*"([^"]+)"/);
      const d = String(raw).match(/"divergencias"\s*:\s*"([\s\S]*?)"\s*,\s*"fontes"/);
      const f = String(raw).match(/"fontes"\s*:\s*"([\s\S]*?)"?\s*\}?\s*$/);
      if (s && ALLOWED.includes(s[1])) status = s[1];
      divergencias = d ? clean(d[1]) : 'Não foi possível extrair estruturado. Texto bruto: ' + clean(raw);
      fontes = f ? clean(f[1]) : '';
    }
  }
  return { json: { status_factual: status, divergencias, fontes } };
});
